// Content Scores
// =====================
func (q *Queries) UpsertContentScore(ctx context.Context, arg UpsertContentScoreParams) (ContentScore, error) {
	row := q.db.QueryRow(ctx, upsertContentScore,
		arg.ContentID,
		arg.VoteScore,
		arg.CommentCount,
		arg.ViewCount,
		arg.BookmarkCount,
		arg.VelocityScore,
	)
	var i ContentScore
	err := row.Scan(
		&i.ContentID,
		&i.VoteScore,
		&i.CommentCount,
		&i.ViewCount,
		&i.BookmarkCount,
		&i.VelocityScore,
		&i.RelevanceEmbedding,
		&i.LastScoredAt,
	)
	return i, err
}

